<?php
require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';$user=Auth::requireRole('hospital');$hospital=current_hospital($user);if(!request_method('POST'))redirect('hospital/inventory.php');Csrf::verify();$id=(int)($_POST['id']??0);$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT * FROM blood_transfer_requests WHERE id=? AND to_hospital_id=? AND status='accepted' FOR UPDATE");$q->execute([$id,(int)$hospital['id']]);$t=$q->fetch();if(!$t)throw new RuntimeException('Transfer completion is not allowed.');$stock=$pdo->prepare('SELECT units_available FROM blood_inventory WHERE hospital_id=? AND blood_group=? FOR UPDATE');$stock->execute([(int)$t['from_hospital_id'],$t['blood_group']]);$available=(int)($stock->fetchColumn()?:0);if($available<(int)$t['units_requested'])throw new RuntimeException('Supplying hospital no longer has enough prototype stock.');$pdo->prepare('UPDATE blood_inventory SET units_available=units_available-? WHERE hospital_id=? AND blood_group=?')->execute([(int)$t['units_requested'],(int)$t['from_hospital_id'],$t['blood_group']]);$pdo->prepare('INSERT INTO blood_inventory(hospital_id,blood_group,units_available) VALUES(?,?,?) ON DUPLICATE KEY UPDATE units_available=units_available+VALUES(units_available)')->execute([(int)$t['to_hospital_id'],$t['blood_group'],(int)$t['units_requested']]);$pdo->prepare("UPDATE blood_transfer_requests SET status='completed',completed_at=NOW() WHERE id=?")->execute([$id]);$pdo->commit();audit('transfer_completed','transfer',$id);flash('success','Transfer marked completed and prototype inventory quantities updated.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}redirect('hospital/inventory.php');
